export const intangiblesQuiz: Quiz = {
  key: "intangibles",
  title: "Intangible Assets, Impairment, R&D, and Software Costs",
  subtitle: "Intangible Assets, Impairment, R&D, and Software Costs",
  discipline: "intermediate",
  course: "intermediate",
  questions: [
    {
      id: "4967",
      prompt: `Which of the following types of assets would typically be reported on a company's balance sheet as an intangible asset?`,
      choices: [
        `Derivative securities.`,
        `Cost of research and development.`,
        `Leasehold improvements.`,
        `Cost of patent registrations.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. Cost of patent registrations is correct.</strong> Registration costs buy a legally protected right with no physical substance, so they are capitalized as an intangible asset.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">An intangible asset <strong style="color:var(--mx-navy)">lacks physical substance</strong>, is <strong style="color:var(--mx-navy)">identifiable</strong> or arises from legal or contractual rights, and provides <strong style="color:var(--mx-navy)">future economic benefit</strong> at a measurable cost (<strong style="color:var(--mx-navy)">ASC 350</strong>). Filing fees and legal fees paid to secure a patent meet every part of that test, so they are capitalized and then amortized over the shorter of the legal life or the useful life.</p><p style="margin:0 0 18px">The trap is assuming that anything non-physical is an intangible. Financial instruments are non-physical but report as <strong style="color:var(--mx-navy)">financial assets</strong> at fair value. Internally generated <strong style="color:var(--mx-navy)">research and development is expensed as incurred</strong> under US GAAP, even when it produces the very invention being patented. And an improvement bolted to leased space is <strong style="color:var(--mx-navy)">tangible property</strong>. Only the cost of obtaining the legal right itself lands in the intangibles section.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry to record registration costs</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Patents</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$10,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$10,000</td></tr></tbody></table></div><p style="margin:0 0 18px">The research spent developing the invention stays in expense. Only the outlays to obtain and defend the legal right are capitalized here.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Derivative securities.</strong> Financial instruments carried at fair value, reported as financial assets or liabilities, not intangibles.<br /><strong style="color:var(--mx-navy)">B. Cost of research and development.</strong> Expensed as incurred under US GAAP, so no asset is recorded at all.<br /><strong style="color:var(--mx-navy)">C. Leasehold improvements.</strong> Physical modifications to leased space, reported in property, plant and equipment and depreciated.</p></div>`,
    },
    {
      id: "4966",
      prompt: `A company recently acquired a copyright that now has a remaining legal life of 30 years. The copyright initially had a 38-year useful life assigned to it. An analysis of market trends and consumer habits indicated that the copyrighted material will generate positive cash flows for approximately 25 years.

What is the remaining useful life, if any, over which the company can amortize the copyright for accounting purposes?`,
      choices: [
        `0 years.`,
        `25 years.`,
        `30 years.`,
        `38 years.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. 25 years is correct.</strong> The copyright is amortized over the period it actually produces cash flows, which is shorter than both its legal life and the original estimate.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A finite-lived intangible is amortized over its <strong style="color:var(--mx-navy)">useful life</strong>, meaning the period over which it is expected to contribute to the entity's <strong style="color:var(--mx-navy)">cash flows</strong> (<strong style="color:var(--mx-navy)">ASC 350</strong>). The <strong style="color:var(--mx-navy)">legal life</strong> is only a ceiling: an asset can never be amortized over a period longer than the legal protection, but it is often amortized over less.</p><p style="margin:0 0 18px">Here the three candidate periods are 38 years (the original estimate), 30 years (the remaining legal protection) and 25 years (the economic benefit period). Take the <strong style="color:var(--mx-navy)">shortest</strong>, 25 years. The earlier 38-year assumption is stale, and updating it is a <strong style="color:var(--mx-navy)">change in accounting estimate</strong> applied <strong style="color:var(--mx-navy)">prospectively</strong>, not a restatement of prior periods.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry each year</h3><p style="margin:0 0 10px">Assuming a $1,000,000 carrying amount, annual amortization is $1,000,000 / 25 = $40,000.</p><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Amortization expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$40,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Accumulated amortization, copyright</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$40,000</td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. 0 years.</strong> The copyright still generates benefits, so it is neither fully impaired nor indefinite-lived.<br /><strong style="color:var(--mx-navy)">C. 30 years.</strong> That is the legal life, which caps the period but does not set it when the economic life is shorter.<br /><strong style="color:var(--mx-navy)">D. 38 years.</strong> That is the superseded original estimate, and it exceeds the remaining legal protection as well.</p></div>`,
    },
    {
      id: "8325",
      prompt: `ByteWise Inc. incurred $60,000 in legal fees for the successful registration of a new software patent. After registration, the company spent an additional $70,000 in legal fees to successfully defend the patent in a lawsuit, ensuring its exclusive rights. The patent has a useful life of 10 years. What total amount should ByteWise Inc. capitalize for the patent?`,
      choices: [
        `$60,000`,
        `$70,000`,
        `$130,000`,
        `$0`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. $130,000 is correct.</strong> Both the registration fees and the fees for the successful defense become part of the patent's carrying amount.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A purchased or internally registered patent is carried at the costs <strong style="color:var(--mx-navy)">directly incurred to secure the legal right</strong> (<strong style="color:var(--mx-navy)">ASC 350</strong>). Registration legal fees, filing fees and application costs are <strong style="color:var(--mx-navy)">capitalized</strong> and amortized over the shorter of the legal life or the useful life.</p><p style="margin:0 0 18px">Litigation is where the question is decided. A <strong style="color:var(--mx-navy)">successful defense</strong> preserves the exclusive right and creates future benefit, so those legal fees are <strong style="color:var(--mx-navy)">added to the patent account</strong> and amortized over the remaining life. An <strong style="color:var(--mx-navy)">unsuccessful defense</strong> protects nothing: the legal fees are <strong style="color:var(--mx-navy)">expensed</strong> and the remaining carrying amount is written off. ByteWise won, so the full $70,000 is capitalized alongside the $60,000.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Legal fees, successful registration</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$60,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Legal fees, successful defense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">70,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Capitalized cost of patent</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$130,000</strong></td></tr><tr><td style="border:0; padding:11px 14px">Annual amortization, $130,000 / 10 years</td><td style="border:0; padding:11px 14px; text-align:right">$13,000</td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entries</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Patent (registration)</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$60,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Cash</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$60,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Patent (successful defense)</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$70,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$70,000</td></tr></tbody></table></div><p style="margin:0">The patent then carries at $130,000 and runs through income at <strong style="color:var(--mx-navy)">$13,000 a year</strong> over its 10-year useful life.</p></div>`,
    },
    {
      id: "8328",
      prompt: `Global Brands Inc. acquires a smaller company and with it, a trademark that has a fair value of $150,000 at the acquisition date. The trademark has a remaining legal life of 15 years but can be renewed indefinitely at minimal cost. Global Brands intends to renew the trademark and use it indefinitely. How should Global Brands account for the trademark in its financial statements?`,
      choices: [
        `Amortize over 15 years as a finite-lived intangible asset.`,
        `Not recognized as it cannot be reliably measured.`,
        `Recognize as an expense due to the renewal costs.`,
        `Not amortize and test annually for impairment as an indefinite-lived intangible asset.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. Not amortize and test annually for impairment as an indefinite-lived intangible asset is correct.</strong> Renewal at minimal cost, plus the intent to renew, means there is no foreseeable limit on the cash flows the trademark will produce.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">An intangible asset is amortized only when its useful life is <strong style="color:var(--mx-navy)">finite</strong>. Useful life is an <strong style="color:var(--mx-navy)">economic</strong> question, not a legal one (<strong style="color:var(--mx-navy)">ASC 350</strong>). When the entity can renew the right at <strong style="color:var(--mx-navy)">minimal cost</strong> and intends to do so, the expected renewals are folded into the useful life, and a 15-year legal term becomes irrelevant.</p><p style="margin:0 0 18px">An <strong style="color:var(--mx-navy)">indefinite-lived</strong> intangible is carried at cost less impairment and tested <strong style="color:var(--mx-navy)">at least annually</strong>, and more often when events suggest the carrying amount is not recoverable. Impairment equals the excess of carrying amount over <strong style="color:var(--mx-navy)">fair value</strong>. The small renewal fees are <strong style="color:var(--mx-navy)">expensed as incurred</strong> and do not change the classification. If a limit on the asset's life later becomes foreseeable, it is reclassified as finite-lived and amortized <strong style="color:var(--mx-navy)">prospectively</strong> over the remaining life.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry at acquisition</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Trademark, at fair value</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$150,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Consideration transferred</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$150,000</td></tr></tbody></table></div><p style="margin:0 0 18px">No amortization entry follows in any later period. The only subsequent charge is an impairment loss, if one is indicated.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A.</strong> Confuses the 15-year legal term with the useful life, which the low-cost renewals extend indefinitely.<br /><strong style="color:var(--mx-navy)">B.</strong> The trademark was measured reliably at its $150,000 acquisition-date fair value.<br /><strong style="color:var(--mx-navy)">C.</strong> Intangibles acquired in a business combination are capitalized; only the renewal fees themselves are expensed.</p></div>`,
    },
    {
      id: "8330",
      prompt: `A corporation acquires an existing trademark through a business combination. The trademark has a finite useful life of 15 years based on a contractual agreement with the original creator, and the company determines that its estimated useful life equals the full contractual term of 15 years. How should the trademark be amortized under U.S. GAAP?`,
      choices: [
        `Over its legal life of 15 years using the straight-line method.`,
        `Over the estimated useful life, which could be less than 15 years, based on the company’s assessment.`,
        `Not amortized, as trademarks are considered to have indefinite lives.`,
        `Using an accelerated method to match the pattern in which the economic benefits are consumed.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. Over its legal life of 15 years using the straight-line method is correct.</strong> The useful life equals the 15-year contractual term and no reliable pattern of benefit consumption exists, so the cost is spread evenly over 15 years.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">An intangible with a <strong style="color:var(--mx-navy)">finite life</strong> is amortized over its useful life, and that life can never exceed the legal or contractual period that gives the asset its value (<strong style="color:var(--mx-navy)">ASC 350</strong>). Here the contract runs 15 years and management concluded the economic benefits run for the full term, so the <strong style="color:var(--mx-navy)">amortization period is 15 years</strong>. Shortening it would require evidence that the benefits stop earlier, and there is none. Only <strong style="color:var(--mx-navy)">indefinite-lived</strong> intangibles escape amortization; those are tested for impairment at least annually instead.</p><p style="margin:0 0 18px">The method must follow the <strong style="color:var(--mx-navy)">pattern in which the economic benefits are consumed</strong>. When that pattern cannot be reliably determined, and for a trademark it rarely can, <strong style="color:var(--mx-navy)">straight-line</strong> is the required default. <strong style="color:var(--mx-navy)">Residual value is presumed zero</strong> unless a third party has committed to buy the asset at the end of its life, so the entire cost runs through expense across the term.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry each year</h3><p style="margin:0 0 10px">Assume a $1,500,000 acquisition cost: $1,500,000 / 15 = $100,000 per year.</p><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Amortization expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$100,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Accumulated amortization, trademark</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$100,000</td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B.</strong> The company already assessed the useful life as the full 15 years, so there is no shorter period to use.<br /><strong style="color:var(--mx-navy)">C.</strong> Trademarks are indefinite-lived only when renewal is expected without substantial cost; this one is capped by a 15-year contract.<br /><strong style="color:var(--mx-navy)">D.</strong> An accelerated pattern is used only when the consumption pattern is reliably measurable, which it is not here.</p></div>`,
    },
    {
      id: "4968",
      prompt: `After an impairment loss is recognized, the adjusted carrying amount of the intangible asset shall be its new accounting basis. Which of the following statements about subsequent reversal of a previously recognized impairment loss is correct under U.S. GAAP?`,
      choices: [
        `It is prohibited.`,
        `It is required when the reversal is considered permanent.`,
        `It must be disclosed in the notes to the financial statements.`,
        `It is encouraged, but not required.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. It is prohibited is correct.</strong> Once an intangible asset is written down, that lower amount is its <strong style="color:var(--mx-navy)">new accounting basis</strong>, and U.S. GAAP never writes it back up.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">An impairment loss reduces the carrying amount of the intangible to its <strong style="color:var(--mx-navy)">fair value</strong>, and that written-down figure becomes the asset's basis going forward (<strong style="color:var(--mx-navy)">ASC 350</strong>). Any future amortization is computed on the new, lower amount over the remaining useful life. The impairment test is run again in later years only to look for <strong style="color:var(--mx-navy)">further</strong> declines, never to measure a recovery.</p><p style="margin:0 0 18px">Later increases in value are simply ignored. <strong style="color:var(--mx-navy)">Reversal</strong> of a previously recognized impairment loss on an asset <strong style="color:var(--mx-navy)">held for use</strong> is prohibited, whether the asset is goodwill, another intangible, or property, plant and equipment. The one narrow exception sits elsewhere: a long-lived asset classified as <strong style="color:var(--mx-navy)">held for sale</strong> may be written back up, but never above its carrying amount before the write-down. Know the contrast: <strong style="color:var(--mx-navy)">IFRS</strong> does permit reversals for intangibles other than goodwill.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry that creates the new basis</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Impairment loss</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$XXX</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Intangible asset</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$XXX</td></tr></tbody></table></div><p style="margin:0 0 18px">No contra-asset account is used. The asset is credited directly, which is exactly why there is nothing to restore later.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B.</strong> Confuses reversal with the "permanent decline" language used in other impairment models; permanence is irrelevant because no reversal is ever allowed.<br /><strong style="color:var(--mx-navy)">C.</strong> Disclosure applies to the impairment loss itself, not to a reversal that cannot be recorded.<br /><strong style="color:var(--mx-navy)">D.</strong> Describes the IFRS approach, not U.S. GAAP, which flatly bars the write-up.</p></div>`,
    },
    {
      id: "8844",
      prompt: `A company holds a patent that it purchased for $140,000. As of the end of the current year, the carrying amount of the patent is $90,000. Because of technological changes, the patent might be impaired. Management estimates that before the patent expires, it will generate net cash flows of $80,000 that have a discounted present value of $74,000. What amount, if any, should the company recognize as an impairment loss for the current year?`,
      choices: [
        `$0`,
        `$10,000`,
        `$16,000`,
        `$66,000`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. $16,000 is correct.</strong> The patent fails the recoverability test, so it is written down from its $90,000 carrying amount to its $74,000 fair value.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A long-lived asset held for use is tested in <strong style="color:var(--mx-navy)">two steps</strong> (<strong style="color:var(--mx-navy)">ASC 360</strong>). Step one is the <strong style="color:var(--mx-navy)">recoverability test</strong>: compare the carrying amount to the sum of the expected <strong style="color:var(--mx-navy)">undiscounted</strong> future cash flows. Here $90,000 exceeds $80,000, so the asset cannot recover its book value through use and it is impaired.</p><p style="margin:0 0 18px">Step two <strong style="color:var(--mx-navy)">measures</strong> the loss, and it uses a different number: carrying amount minus <strong style="color:var(--mx-navy)">fair value</strong>. The undiscounted cash flows are only the trigger, never the measurement. Fair value here is the <strong style="color:var(--mx-navy)">discounted present value</strong> of $74,000, and the write-down is taken against the asset itself, not against original cost. Going forward, amortization runs on the new $74,000 basis over the remaining life, and the loss cannot be <strong style="color:var(--mx-navy)">reversed</strong> later.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Carrying amount</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$90,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Undiscounted cash flows (trigger only)</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$80,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Fair value, present value of cash flows</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(74,000)</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Impairment loss, $90,000 - $74,000</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$16,000</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Impairment loss</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$16,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Patent</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$16,000</td></tr></tbody></table></div><p style="margin:0">The $140,000 original cost and the $50,000 of accumulated amortization already sit inside the $90,000 carrying amount, so neither figure enters the calculation again.</p></div>`,
    },
    {
      id: "4971",
      prompt: `Which of the following intangible assets would be subject to the recoverability test when assessing impairment?`,
      choices: [
        `A patent`,
        `Goodwill`,
        `R&D costs for a patent.`,
        `A trademark with indefinite useful life.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. A patent is correct.</strong> A patent has a <strong style="color:var(--mx-navy)">finite useful life</strong>, so its impairment test begins with the undiscounted cash flow recoverability screen.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Finite-lived intangibles, such as patents, copyrights with a fixed term, customer lists and licenses, are tested in two steps once a <strong style="color:var(--mx-navy)">triggering event</strong> occurs. Step one is the <strong style="color:var(--mx-navy)">recoverability test</strong>: compare the carrying amount with the sum of the <strong style="color:var(--mx-navy)">undiscounted</strong> future cash flows expected from use and eventual disposal. If those cash flows equal or exceed carrying amount, stop, there is no impairment, even if fair value is lower.</p><p style="margin:0 0 18px">Only if the asset fails step one do you measure the loss as carrying amount minus <strong style="color:var(--mx-navy)">fair value</strong>. Intangibles with an <strong style="color:var(--mx-navy)">indefinite life</strong>, including goodwill, skip the recoverability test entirely (<strong style="color:var(--mx-navy)">ASC 350</strong>) and are compared directly to fair value. That is the whole distinction the question is testing: undiscounted cash flow screen for finite lives, straight fair value comparison for indefinite lives.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry if the patent fails step one</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Impairment loss</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">XXX</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Patent</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">XXX</td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Goodwill.</strong> Indefinite-lived and tested at the reporting unit level by comparing carrying amount to fair value, with no cash flow screen.<br /><strong style="color:var(--mx-navy)">C. R&amp;D costs for a patent.</strong> Internal research and development is expensed as incurred, so there is no capitalized asset to impair.<br /><strong style="color:var(--mx-navy)">D. A trademark with indefinite useful life.</strong> Not amortized and not screened for recoverability, it goes straight to the fair value comparison.</p></div>`,
    },
    {
      id: "7985",
      prompt: `On December 1, year 2, a company was formed and incurred the following costs:

$12,000 to purchase an accounting software system, $5,000 in legal fees to draft the stock purchase agreement, and $8,000 to print and register the preferred stock certificates.

The company amortizes the software using the straight-line method over its estimated useful life of four years, and the software has no residual value.

At December 31, year 2, the company should report what amount of total assets?`,
      choices: [
        `$11,750`,
        `$12,000`,
        `$20,000`,
        `$24,750`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. $11,750 is correct.</strong> Only the accounting software is an asset, and one month of amortization has already come off it.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Two of the three outlays never touch the asset side of the balance sheet. <strong style="color:var(--mx-navy)">Organization costs</strong>, such as legal fees to draft the stock purchase agreement, are <strong style="color:var(--mx-navy)">expensed as incurred</strong> because they create no separately identifiable future benefit. Costs to <strong style="color:var(--mx-navy)">print and register stock certificates</strong> are direct costs of issuing equity, so they are charged against the issuance proceeds rather than capitalized. Either way, the $5,000 and the $8,000 are gone by December 31.</p><p style="margin:0 0 18px">Purchased software is a <strong style="color:var(--mx-navy)">capitalized intangible asset</strong> reported at cost less accumulated amortization. Amortization begins when the asset is <strong style="color:var(--mx-navy)">placed in service</strong>, here December 1, and runs <strong style="color:var(--mx-navy)">straight line</strong> over the four-year useful life with no residual value. Only <strong style="color:var(--mx-navy)">one month</strong> of that life has elapsed at the balance sheet date.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Software cost capitalized</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$12,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Annual amortization, $12,000 / 4 years</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$3,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">One month, $3,000 x 1/12</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(250)</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Legal fees and stock certificate costs</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$0</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Total assets at December 31, year 2</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$11,750</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entries</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Software</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$12,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Organization expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$5,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Additional paid-in capital</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$8,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Cash</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$25,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Amortization expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$250</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Accumulated amortization</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$250</td></tr></tbody></table></div><p style="margin:0">Cash fell by $25,000 and only $11,750 of that spending survives as an asset. The software line is the entire asset section unless the problem gives you remaining cash, which it does not.</p></div>`,
    },
    {
      id: "7998",
      prompt: `A company purchased an intangible asset by paying $50,000 cash and transferring to the seller a parcel of land, which the company had originally purchased for $32,000. At the time of transfer, the land had a fair value of $41,000, and the company paid $3,000 to a real estate attorney to finalize the transaction.

What amount should the company record as the intangible asset's cost?`,
      choices: [
        `$82,000`,
        `$85,000`,
        `$91,000`,
        `$94,000`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. $94,000 is correct.</strong> Cash of $50,000, the land at its $41,000 fair value, and the $3,000 attorney fee all enter the asset's cost.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">An asset acquired with <strong style="color:var(--mx-navy)">noncash consideration</strong> is recorded at the <strong style="color:var(--mx-navy)">fair value of what the buyer gives up</strong>, not at what that consideration originally cost. The land's $32,000 historical cost is irrelevant to the intangible's basis; its $41,000 fair value measures what the company actually paid. <strong style="color:var(--mx-navy)">Book value</strong> matters only for computing the gain or loss on the land surrendered.</p><p style="margin:0 0 18px">Costs <strong style="color:var(--mx-navy)">directly attributable</strong> to getting the asset ready for its intended use are capitalized too, so the $3,000 real estate attorney fee belongs in the cost, not in expense. Costs incurred after the asset is ready, such as training or routine maintenance, are <strong style="color:var(--mx-navy)">expensed as incurred</strong>. The fair value of the intangible received could be used instead if it were more clearly evident, but here the consideration given is the observable measure.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Cash paid</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$50,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Fair value of land transferred</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$41,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Attorney fee to close the transaction</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$3,000</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Cost of the intangible asset</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$94,000</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Intangible asset</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$94,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Cash</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$53,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Land</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$32,000</td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Gain on disposal of land</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$9,000</td></tr></tbody></table></div><p style="margin:0 0 12px">The land leaves the books at its $32,000 carrying amount, the intangible comes in at $94,000, and the $9,000 difference is recognized as a <strong style="color:var(--mx-navy)">gain</strong>. Cash credited is $53,000: the $50,000 paid to the seller plus the $3,000 legal fee.</p><p style="margin:0">When consideration is a mix of cash and property, split the question in two. First measure the new asset at cash plus the fair value of the property plus <strong style="color:var(--mx-navy)">direct closing costs</strong>. Then derecognize the property given up at its own <strong style="color:var(--mx-navy)">carrying amount</strong> and let the difference fall to gain or loss. Mixing the two steps is what produces a wrong basis.</p></div>`,
    },
  ],
};
